#!/bin/bash
# Generated by v32lua 20261018-dev for vircout.lua.
# Edit freely: v32lua leaves a Make.sh it did not write alone, and
# --no-build-scripts stops it writing these.

# define an abort function to call on error
abort_build()
{
    echo
    echo BUILD FAILED
    exit 1
}

# work from the folder this script is in
cd "$(dirname "$0")" || abort_build

# v32lua is needed to build this project
if ! command -v v32lua >/dev/null 2>&1; then
    echo
    echo "ERROR: v32lua is needed to build this project, but it was not found in your PATH"
    abort_build
fi

# create the output folders if non existing, since
# the development tools will not create them themselves
mkdir -p obj
mkdir -p bin

echo
echo Compile the Lua code
echo --------------------------
v32lua --no-build-scripts -o obj/vircout.asm vircout.lua || abort_build

echo
echo Convert the PNG textures
echo --------------------------
png2vircon assets/sprites.png -o obj/sprites.vtex || abort_build
png2vircon assets/title.png -o obj/title.vtex || abort_build
png2vircon assets/gameplay.png -o obj/gameplay.vtex || abort_build
png2vircon assets/ending.png -o obj/ending.vtex || abort_build

echo
echo Convert the WAV sounds
echo --------------------------
wav2vircon audio/music_title.wav -o obj/music_title.vsnd || abort_build
wav2vircon audio/music_gameplay.wav -o obj/music_gameplay.vsnd || abort_build
wav2vircon audio/music_ending.wav -o obj/music_ending.vsnd || abort_build
wav2vircon audio/sfx_paddle.wav -o obj/sfx_paddle.vsnd || abort_build
wav2vircon audio/sfx_wall.wav -o obj/sfx_wall.vsnd || abort_build
wav2vircon audio/sfx_normal.wav -o obj/sfx_normal.vsnd || abort_build
wav2vircon audio/sfx_hard_hit.wav -o obj/sfx_hard_hit.vsnd || abort_build
wav2vircon audio/sfx_hard_break.wav -o obj/sfx_hard_break.vsnd || abort_build
wav2vircon audio/sfx_metal.wav -o obj/sfx_metal.vsnd || abort_build
wav2vircon audio/sfx_item.wav -o obj/sfx_item.vsnd || abort_build
wav2vircon audio/sfx_laser.wav -o obj/sfx_laser.vsnd || abort_build
wav2vircon audio/sfx_ball_lost.wav -o obj/sfx_ball_lost.vsnd || abort_build
wav2vircon audio/sfx_level_clear.wav -o obj/sfx_level_clear.vsnd || abort_build
wav2vircon audio/sfx_game_over.wav -o obj/sfx_game_over.vsnd || abort_build
wav2vircon audio/sfx_cheat.wav -o obj/sfx_cheat.vsnd || abort_build

echo
echo Assemble the ASM code
echo --------------------------
assemble obj/vircout.asm -o obj/vircout.vbin || abort_build

echo
echo Pack the ROM
echo --------------------------
packrom obj/vircout.xml -o bin/vircout.v32 || abort_build

if command -v v32opt >/dev/null 2>&1; then
    echo
    echo Build the optimized cart \(v32opt\)
    echo --------------------------
    if v32opt -O3 -o obj/vircoutOpt.asm obj/vircout.asm \
       && assemble obj/vircoutOpt.asm -o obj/vircoutOpt.vbin \
       && packrom obj/vircoutOpt.xml -o bin/vircoutOpt.v32; then
        :
    else
        echo
        echo "WARNING: the optimized build failed; the regular cart was still built"
    fi
else
    echo
    echo "v32opt was not found in your PATH: skipping the optimized build"
fi

echo
echo BUILD SUCCESSFUL
